"""Client clarification drafts. Built from templates, not generated by an LLM:
the Squad Lead reviews and posts them, so they must be predictable."""

from .models import PASS, Verdict


def human_join(items: list[str]) -> str:
    return items[0] if len(items) == 1 else ", ".join(items[:-1]) + " and " + items[-1]


def _banned_ask(phrases: list[str]) -> str:
    quoted = human_join([f"\"{p}\"" for p in phrases])
    which = "is on the list of claims" if len(phrases) == 1 else "are on the list of claims"
    return f"The copy includes {quoted}, which {which} we've agreed not to use. Could you share an alternative line?"


def _asks(v: Verdict, audience: str) -> list[str]:
    banned = [r.evidence for r in v.reasons if r.code == "banned_claim" and r.evidence]
    asks = []
    for r in v.reasons:
        if r.audience != audience or not r.client_ask:
            continue
        if r.code == "banned_claim":
            # All banned phrases go into one ask, placed where the first one was.
            ask = _banned_ask(banned)
        elif r.code == "brain_rule" and any(b.casefold() in (r.evidence or "").casefold() for b in banned):
            # A Brain-rule hit on the same words as a banned phrase is one
            # problem for the client, so ask about it once.
            continue
        else:
            ask = r.client_ask
        if ask not in asks:
            asks.append(ask)
    return asks


def compose(title: str, asks: list[str]) -> str:
    if len(asks) == 1:
        body = f"one quick check: {asks[0][0].lower()}{asks[0][1:]}"
    else:
        body = "a few quick checks:\n" + "\n".join(f"• {a}" for a in asks)
    return (f"Hi team, before we start on \"{title}\", {body}\n"
            f"As soon as we hear back, it goes straight into production.")


def attach(v: Verdict) -> None:
    if v.status == PASS:
        return
    client_asks = _asks(v, "client")
    approval_asks = _asks(v, "approval")
    if client_asks:
        # We are messaging the client anyway: ask everything in one message.
        v.client_message = compose(v.title, client_asks + approval_asks)
    elif approval_asks:
        # The Squad Lead can unblock this alone; only if they decline does
        # the client hear about it.
        v.client_message_if_declined = compose(v.title, approval_asks)
